 "content": "from collections import Counter


def transform(grid):
    """Copy the sparse nonzero motif into every matching all-zero location."""
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    motif_colors = [value for value in counts if value not in (0, background)]
    if not motif_colors:
        return [row[:] for row in grid]

    color = min(motif_colors, key=lambda value: counts[value])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    rmin = min(r for r, _ in points)
    cmin = min(c for _, c in points)
    shape = [(r - rmin, c - cmin) for r, c in points]
    shape_h = max(r for r, _ in shape) + 1
    shape_w = max(c for _, c in shape) + 1

    out = [row[:] for row in grid]
    for r0 in range(h - shape_h + 1):
        for c0 in range(w - shape_w + 1):
            cells = [(r0 + dr, c0 + dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = color
    return out


